class Cell:
 def forward(self,value,replacement):
  self._modules["second"] = replacement
  value=self.first(value)
  return self.second(value)

class Cell:
 def forward(self,value,replacement):
  self.__dict__["second"] = replacement
  value=self.first(value)
  return self.second(value)

class Cell:
 def forward(self,value,replacement):
  del self.second
  value=self.first(value)
  return self.second(value)
